# Vital signs and Glasgow Coma Scale components:
def calculate_apache_score(age, heart_rate, mean_bp, respiratory_rate, temperature, Glasgow_score):
    apache_score = 0

    if age >= 70:
        apache_score += 4
    elif age >= 55:
        apache_score += 3
    elif age >= 45:
        apache_score += 2
    elif age >= 18:
        apache_score += 1

    if heart_rate >= 180:
        apache_score += 4
    elif heart_rate >= 160:
        apache_score += 3
    elif heart_rate >= 140:
        apache_score += 2
    elif heart_rate >= 110:
        apache_score += 1

    if mean_bp < 70:
        apache_score += 4
    elif mean_bp < 80:
        apache_score += 3
    elif mean_bp < 100:
        apache_score += 2
    elif mean_bp < 110:
        apache_score += 1

    if respiratory_rate >= 50:
        apache_score += 4
    elif respiratory_rate >= 35:
        apache_score += 3
    elif respiratory_rate >= 25:
        apache_score += 2
    elif respiratory_rate >= 12:
        apache_score += 1

    if temperature < 34:
        apache_score += 4
    elif temperature < 32:
        apache_score += 3
    elif temperature < 30:
        apache_score += 2
    elif temperature < 26:
        apache_score += 1

    apache_score += (15 - Glasgow_score)

    return apache_score

# Laboratory values component:
def calculate_lab_score(sodium, potassium, creatinine, wbcc, hematocrit):
    apache_score = 0

    if sodium < 120:
        apache_score += 4
    elif sodium < 130:
        apache_score += 3
    elif sodium < 140:
        apache_score += 2
    elif sodium < 155:
        apache_score += 1

    if potassium < 2.5:
        apache_score += 4
    elif potassium < 3.0:
        apache_score += 3
    elif potassium < 3.5:
        apache_score += 2
    elif potassium < 5.0:
        apache_score += 1

    if creatinine >= 5.0:
        apache_score += 4
    elif creatinine >= 3.5:
        apache_score += 3
    elif creatinine >= 2.0:
        apache_score += 2
    elif creatinine >= 1.5:
        apache_score += 1

    if wbcc >= 40_000 or wbcc < 1_000:
        apache_score += 4
    elif wbcc >= 30_000 or wbcc < 1_500:
        apache_score += 3
    elif wbcc >= 20_000 or wbcc < 2_000:
        apache_score += 2
    elif wbcc >= 15_000 or wbcc < 4_000:
        apache_score += 1

    if hematocrit < 20:
